  const navLink = ([path,glyph,name]) => `<button class="nav-item ${route()===path || (path==='profile'&&route()==='orders') ? 'selected':''}" data-action="navigate" data-route="${path}" aria-label="${name}">${icon(glyph,20)}<span>${name}</span>${path==='cart'&&model.cart.length?`<b class="nav-count">${model.cart.reduce((s,x)=>s+x.qty,0)}</b>`:''}</button>`;
  const sidebar = () => `<aside class="sidebar ${ui.sidebar?'sidebar-open':''}"><div class="sidebar-section"><div class="sidebar-label">Покупателю</div>${topNav.map(navLink).join('')}</div><div class="sidebar-section"><div class="sidebar-label">Для бизнеса</div>${sellerNav.map(navLink).join('')}</div><div class="sidebar-footer"><div class="pilot-mark">${icon('spark',16)} Продуктовый пилот · 2026</div><button data-action="reset" class="reset-link">${icon('refresh',16)} Сбросить демо</button></div></aside>`;
  const head = () => `<header class="topbar"><div class="topbar-inner"><button class="mobile-menu icon-btn" aria-label="Открыть меню" data-action="toggle-sidebar">${icon('grid',22)}</button><button class="brand" data-action="navigate" data-route="market"><span class="brand-mark">vk</span><span>маркет</span><small>beta</small></button><form class="global-search" data-form="global-search"><span>${icon('search',18)}</span><input name="q" value="${escapeHTML(ui.query)}" placeholder="Поиск по товарам и магазинам" aria-label="Поиск товаров"/><button aria-label="Искать" type="submit">${icon('arrow',17)}</button></form><div class="header-actions"><span class="demo-pill">Демо-версия</span><button class="icon-btn theme-btn" aria-label="Сменить тему" title="Сменить тему" data-action="theme">${icon(model.theme==='dark'?'sun':'moon',20)}</button><button class="header-cart icon-btn" aria-label="Корзина" title="Корзина" data-action="navigate" data-route="cart">${icon('cart',20)}${model.cart.length?'<i></i>':''}</button><button class="avatar-btn" title="Профиль" data-action="navigate" data-route="profile">ВК</button></div></div></header>`;
  const pImage = (p, type='') => `<div class="product-visual ${type}" style="--visual:${escapeHTML(p.color||'#e8ebf0')}">${illustration(p)}<img src="${escapeHTML(p.photo || '')}" alt="${escapeHTML(p.title)}" loading="lazy" onerror="this.style.display='none'" /></div>`;
  const sellerAvatar = (s, size='') => `<span class="seller-avatar ${size}" style="background:${s.color}">${escapeHTML(s.avatar)}</span>`;
  const badge = (label, cls='') => `<span class="status-pill ${cls}">${escapeHTML(label)}</span>`;
  const productCard = (p, index=0) => `<article class="product-card" style="animation-delay:${Math.min(index*45,250)}ms"><button class="product-picture" data-action="navigate" data-route="product/${p.id}" aria-label="Открыть ${escapeHTML(p.title)}">${pImage(p)}${p.badge?`<span class="photo-label">${escapeHTML(p.badge)}</span>`:''}</button><button class="fav-btn ${isFav(p.id)?'on':''}" data-action="favorite" data-id="${p.id}" aria-label="${isFav(p.id)?'Убрать из избранного':'В избранное'}">${icon('heart',18)}</button><div class="product-meta"><div class="product-price">${money(p.price)}${p.oldPrice?`<span class="old-price">${money(p.oldPrice)}</span>`:''}</div><button class="product-title" data-action="navigate" data-route="product/${p.id}">${escapeHTML(p.title)}</button><button class="product-seller" data-action="navigate" data-route="community/${p.seller}">${escapeHTML(community(p.seller).name)}</button><div class="card-actions">${p.stock?`<span class="subtle-stock">${p.stock<4?'Мало осталось':'В наличии'}</span>`:'<span class="out-stock">Нет в наличии</span>'}<button class="circle-action" data-action="add-cart" data-id="${p.id}" ${p.stock?'':'disabled'} aria-label="Добавить в корзину">${icon('plus',18)}</button></div></div></article>`;
  const productsGrid = (arr) => `<div class="products-grid">${arr.map(productCard).join('')}</div>`;
  const dropLabel = (d) => d.status==='live'?'Уже в продаже':d.status==='soldout'?'Распродано':d.status==='ended'?'Завершён':'Скоро старт';
  const dropCard = (d, large=false) => `<button class="drop-card ${large?'drop-large':''}" data-action="navigate" data-route="drop/${d.id}"><div class="drop-image" style="--visual:${d.seller==='archive'?'#d2d8df':'#e5ddd2'}">${illustration(product(d.itemIds[0])||model.products[0])}<img src="${escapeHTML(d.cover)}" alt="" loading="lazy" onerror="this.style.display='none'" /></div><div class="drop-overlay"><span class="drop-badge">${icon('fire',14)} ${dropLabel(d)}</span><div><span class="drop-by">${escapeHTML(community(d.seller).name)}</span><h3>${escapeHTML(d.title)}</h3><p>${escapeHTML(d.subtitle)}</p><span class="drop-link">${d.status==='announced'?dateLabel(d.startsAt,true):'Смотреть коллекцию'} ${icon('arrow',15)}</span></div></div></button>`;
  const pageIntro = (eyebrow,title,sub,actions='') => `<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions?`<div class="page-tools">${actions}</div>`:''}</div>`;
  const sectionHeader = (title,sub='',link='',to='') => `<div class="section-header"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link?`<button class="text-link" data-action="navigate" data-route="${to}">${link} ${icon('arrow',16)}</button>`:''}</div>`;
  const market = () => `<div class="market-page"><div class="hero"><div class="hero-text"><span class="hero-overline">НОВОЕ В VK МАРКЕТЕ <span class="hero-star">✦</span></span><h1>Находки, у которых<br/>есть <em>история</em></h1><p>Покупайте у любимых сообществ, открывайте новые бренды и не пропускайте лимитированные дропы.</p><div class="hero-actions">${button(`Найти своё ${icon('arrow',18)}`,'open-search','primary btn-lg')}${button(`Смотреть дропы ${icon('fire',17)}`,'scroll-drops','light btn-lg')}</div></div><div class="hero-image" role="img" aria-label="Коллекция дизайнерских предметов">${illustration(model.products[3])}<img src="${photos.chair}" alt="Дизайнерский стул"/><div class="hero-floating"><span class="float-icon">${icon('spark',17)}</span><div>Из сообществ VK<br/><strong>Вещи с характером</strong></div></div></div><span class="hero-shape one"></span><span class="hero-shape two"></span></div><div class="benefits"><span>${icon('check',17)} Продавцы из сообществ VK</span><span>${icon('heart',17)} Находки и малые бренды</span><span>${icon('bell',17)} Уведомления о дропах</span></div><section class="block" id="categories">${sectionHeader('Найдите то, что нравится','Пять направлений — тысячи идей')}<div class="category-row">${[['Гардероб','👕','#f2e2ea'],['Дом и дача','⌂','#e6e9da'],['Хобби и развлечения','✦','#eee5ff'],['Продукты питания','◉','#fff0d9'],['Красота и здоровье','✿','#f7e5e3']].map(([n,g,c])=>`<button class="category-tile" data-action="category" data-name="${n}"><span class="category-art" style="background:${c}">${g}</span><span>${n}</span>${icon('arrow',15)}</button>`).join('')}</div></section><section class="block" id="drops">${sectionHeader('Дропы, которые ждут','Ограниченные коллекции из ваших сообществ','Все дропы','studio/drops')}<div class="drop-grid">${model.drops.slice(0,2).map(d=>dropCard(d)).join('')}</div></section><section class="block">${sectionHeader('Вам может понравиться','Необычные товары от независимых продавцов','Смотреть всё','search')}${productsGrid(model.products.slice(0,8))}</section><section class="block">${sectionHeader('Магазины с характером','За каждым товаром — люди и сообщество')}<div class="community-grid">${communities.map(s=>`<button class="community-tile" data-action="navigate" data-route="community/${s.id}">${sellerAvatar(s,'large')}<div><strong>${escapeHTML(s.name)}</strong><p>${escapeHTML(s.category)}</p><small>${s.followers} подписчиков</small></div>${icon('arrow',18)}</button>`).join('')}</div></section></div>`;
  const filteredProducts = (filters = ui) => {
    let arr = model.products.filter(p =>
      (filters.category === 'Все' || p.category === filters.category) &&
      (!ui.query || `${p.title} ${community(p.seller).name} ${p.description}`.toLowerCase().includes(ui.query.toLowerCase())) &&
      (!filters.inStock || p.stock > 0) &&
      (!filters.minPrice || p.price >= Number(filters.minPrice)) &&
      (!filters.maxPrice || p.price <= Number(filters.maxPrice))
    );
    if (ui.sort === 'cheap') arr.sort((a,b) => a.price - b.price);
    if (ui.sort === 'expensive') arr.sort((a,b) => b.price - a.price);
    return arr;
  };
  const activeFilterCount = () => Number(ui.category !== 'Все') + Number(Boolean(ui.minPrice)) + Number(Boolean(ui.maxPrice)) + Number(ui.inStock);
  const filterChips = () => {
    const chips = [];
    if (ui.query) chips.push(['query', `Поиск: ${ui.query}`]);
    if (ui.category !== 'Все') chips.push(['category', ui.category]);
    if (ui.minPrice || ui.maxPrice) chips.push(['price', `Цена: ${ui.minPrice ? money(ui.minPrice) : 'от 0 ₽'} — ${ui.maxPrice ? money(ui.maxPrice) : 'любая'}`]);
    if (ui.inStock) chips.push(['inStock', 'Только в наличии']);
    if (!chips.length) return '';
    return `<div class="active-filters" aria-label="Применённые фильтры">${chips.map(([key,label]) => `<button type="button" class="filter-chip" data-action="remove-filter-chip" data-key="${key}" aria-label="Убрать фильтр: ${escapeHTML(label)}">${escapeHTML(label)} ${icon('close',14)}</button>`).join('')}<button type="button" class="clear-chips" data-action="clear-filters">Сбросить всё</button></div>`;
  };
  const filterDrawer = () => {
    if (!ui.filtersOpen) return '';
    const f = ui.filterDraft || ui;
    const matching = filteredProducts(f).length;
    return `<div class="filter-backdrop" data-action="close-filter-backdrop">
      <section class="filter-drawer" role="dialog" aria-modal="true" aria-labelledby="filter-heading">
        <div class="filter-drawer-head"><div><span class="filter-overline">НАСТРОЙКА ВЫДАЧИ</span><h2 id="filter-heading">Фильтры</h2></div><button type="button" class="filter-drawer-close" data-action="close-filters" aria-label="Закрыть фильтры">${icon('close',21)}</button></div>
        <div class="filter-drawer-content">
          <fieldset class="filter-group"><legend>Категория</legend><div class="filter-categories">${['Все','Продукты питания','Хобби и развлечения','Дом и дача','Гардероб','Красота и здоровье'].map(c => `<label class="filter-radio"><input type="radio" name="filter-category" data-draft-filter="category" value="${escapeHTML(c)}" ${f.category===c?'checked':''}/><span>${escapeHTML(c)}</span></label>`).join('')}</div></fieldset>
          <fieldset class="filter-group"><legend>Цена, ₽</legend><div class="filter-price-fields"><label>От <input type="number" min="0" step="1" placeholder="0" data-draft-filter="minPrice" value="${escapeHTML(f.minPrice)}" inputmode="numeric" /></label><label>До <input type="number" min="0" step="1" placeholder="Любая" data-draft-filter="maxPrice" value="${escapeHTML(f.maxPrice)}" inputmode="numeric" /></label></div><div class="filter-price-presets"><button type="button" data-action="price-preset" data-min="" data-max="1000">До 1 000 ₽</button><button type="button" data-action="price-preset" data-min="1000" data-max="5000">1 000–5 000 ₽</button><button type="button" data-action="price-preset" data-min="5000" data-max="">От 5 000 ₽</button></div></fieldset>
          <fieldset class="filter-group"><legend>Доступность</legend><label class="filter-toggle"><span><strong>Только в наличии</strong><small>Скрыть товары, которых сейчас нет</small></span><input type="checkbox" data-draft-filter="inStock" ${f.inStock?'checked':''}/></label></fieldset>
        </div>
        <div class="filter-drawer-footer"><button type="button" class="filter-reset" data-action="reset-draft-filters">Сбросить</button><button type="button" class="btn primary filter-apply" data-action="apply-filters">Показать <span data-filter-result-count>${fmt.format(matching)}</span> товаров</button></div>
      </section>
    </div>`;
  };
  const search = () => {
    const results = filteredProducts();
    const count = activeFilterCount();
    return `<div class="search-page">${pageIntro('КАТАЛОГ','Поиск товаров','Находите интересные вещи у продавцов из сообществ VK.')}
      <div class="catalog-toolbar"><form class="catalog-search" data-form="catalog-search">${icon('search',19)}<input type="search" name="q" value="${escapeHTML(ui.query)}" placeholder="Название товара или магазина" aria-label="Поиск по каталогу"/><button type="submit" aria-label="Найти товары">${icon('arrow',18)}</button></form>
      <button type="button" class="filter-open-btn ${count?'has-filters':''}" data-action="open-filters" aria-haspopup="dialog" aria-expanded="false">${icon('filter',18)} Фильтры ${count?`<span class="filter-count">${count}</span>`:''}</button>
      <label class="catalog-sort"><span>Сортировка</span><select data-filter="sort" aria-label="Сортировать товары"><option value="popular" ${ui.sort==='popular'?'selected':''}>Популярные</option><option value="cheap" ${ui.sort==='cheap'?'selected':''}>Сначала дешевле</option><option value="expensive" ${ui.sort==='expensive'?'selected':''}>Сначала дороже</option></select></label></div>
      ${filterChips()}<div class="catalog-results-head"><strong>${fmt.format(results.length)} ${results.length%10===1&&results.length%100!==11?'товар':([2,3,4].includes(results.length%10)&&![12,13,14].includes(results.length%100))?'товара':'товаров'}</strong><span>От продавцов ВКонтакте</span></div>
      ${results.length ? productsGrid(results) : empty('search','Ничего не найдено','Попробуйте изменить запрос или сбросить фильтры.','clear-filters','Сбросить фильтры')}</div>`;
  };
  const breadcrumb = (back,title) => `<button class="breadcrumb" data-action="navigate" data-route="${back}">${icon('back',17)} ${title}</button>`;
  const productPage = (id) => { const p=product(id); if(!p)return notFound(); const s=community(p.seller);return `<div class="detail-page">${breadcrumb('search','К каталогу')}<div class="product-detail panel"><div class="detail-gallery">${pImage(p,'detail-photo')}</div><div class="detail-content"><div class="eyebrow">${escapeHTML(p.category)}</div><h1>${escapeHTML(p.title)}</h1><div class="detail-price">${money(p.price)}${p.oldPrice?`<s>${money(p.oldPrice)}</s>`:''}</div><div class="availability ${p.stock?'':'out-stock'}">${icon(p.stock?'check':'info',16)} ${p.stock?`В наличии · ${p.stock} шт.`:'Нет в наличии'}</div>${p.badge?`<div class="tag-row">${badge(p.badge,'soft')}</div>`:''}<div class="detail-buy">${button(`${icon('cart',19)} В корзину`,'add-cart','primary btn-lg',`data-id="${p.id}" ${p.stock?'':'disabled'}`)}${button(icon('heart',20),'favorite',isFav(id)?'outline favorited btn-lg':'outline btn-lg',`data-id="${p.id}" aria-label="В избранное"`)}</div><div class="detail-fine">${icon('truck',17)} Способ доставки и оплаты — при оформлении заказа</div><div class="separator"></div><div class="seller-summary">${sellerAvatar(s)}<div><strong>${escapeHTML(s.name)}</strong><span>${s.followers} подписчиков</span></div><button class="text-link" data-action="navigate" data-route="community/${s.id}">О продавце ${icon('chevron',16)}</button></div><p class="detail-description">${escapeHTML(p.description)}</p>${p.size?`<p class="spec-row"><span>Размер</span><strong>${escapeHTML(p.size)}</strong></p>`:''}${p.condition?`<p class="spec-row"><span>Состояние</span><strong>${escapeHTML(p.condition)}</strong></p>`:''}<p class="spec-row"><span>Категория</span><strong>${escapeHTML(p.category)}</strong></p><div class="seller-link"><a href="${s.url}" target="_blank" rel="noopener noreferrer">${icon('external',16)} Открыть сообщество VK</a><span>В демо переход ведёт на главную VK</span></div></div></div><section class="block">${sectionHeader('От этого продавца')}${productsGrid(model.products.filter(x=>x.seller===p.seller && x.id!==p.id).slice(0,4))}</section></div>`;};
  const communityPage = (id) => {const s=community(id);return `<div class="community-page">${breadcrumb('market','К Маркету')}<div class="community-hero panel"><div class="community-banner" style="--community-accent:${s.color}"><div class="big-watermark">${escapeHTML(s.avatar)}</div></div><div class="community-body">${sellerAvatar(s,'huge')}<div class="community-heading"><div><div class="eyebrow">МАГАЗИН ИЗ СООБЩЕСТВА</div><h1>${escapeHTML(s.name)} <span class="verified">${icon('check',13)}</span></h1><p>${escapeHTML(s.description)}</p><div class="community-hint">${s.followers} подписчиков · ${model.products.filter(p=>p.seller===id).length} товаров</div></div><div class="community-actions">${button(`${icon('heart',18)} ${model.following.includes(id)?'Вы подписаны':'Подписаться'}`,'follow',model.following.includes(id)?'outline':'primary',`data-id="${id}"`)}<a class="btn light" href="${s.url}" target="_blank" rel="noopener noreferrer">${icon('external',17)} Сообщество VK</a></div></div></div></div><section class="block">${sectionHeader('Товары магазина')}${productsGrid(model.products.filter(p=>p.seller===id))}</section></div>`;};
  const favorites = () => {const list=model.products.filter(p=>model.favorites.includes(p.id));return `<div>${pageIntro('ЛИЧНАЯ ПОДБОРКА','Избранное','Сохраняйте понравившееся, чтобы вернуться к нему позже.')}${list.length?productsGrid(list):empty('heart','Пока ничего нет','Нажмите на сердечко у товара — он появится здесь.','open-search','Искать товары')}${model.following.length?`<section class="block">${sectionHeader('Ваши подписки')}<div class="community-grid">${communities.filter(s=>model.following.includes(s.id)).map(s=>`<button class="community-tile" data-action="navigate" data-route="community/${s.id}">${sellerAvatar(s)}<strong>${escapeHTML(s.name)}</strong>${icon('arrow',18)}</button>`).join('')}</div></section>`:''}</div>`;};
  const cartTotal = () => model.cart.reduce((sum,x)=>sum+(product(x.id)?.price||0)*x.qty,0);
  const cart = () => `<div>${pageIntro('ПОКУПКИ','Корзина','Оформление заказа в рамках одного магазина.')}${model.cart.length?`<div class="cart-layout"><div class="panel cart-list">${model.cart.map(item=>{const p=product(item.id);if(!p)return '';return `<div class="cart-item">${pImage(p)}<div class="cart-text"><button class="product-title" data-action="navigate" data-route="product/${p.id}">${escapeHTML(p.title)}</button><span class="muted">${escapeHTML(community(p.seller).name)}</span><strong>${money(p.price)}</strong><button class="remove-item" data-action="remove-cart" data-id="${p.id}">Удалить</button></div><div class="qty-controls"><button data-action="qty-down" data-id="${p.id}" aria-label="Уменьшить">${icon('minus',16)}</button><span>${item.qty}</span><button data-action="qty-up" data-id="${p.id}" aria-label="Увеличить">${icon('plus',16)}</button></div></div>`;}).join('')}</div><aside class="panel order-summary"><h3>Ваш заказ</h3><p>${model.cart.reduce((s,x)=>s+x.qty,0)} товара</p><div class="summary-line"><span>Товары</span><b>${money(cartTotal())}</b></div><div class="summary-line"><span>Доставка</span><span>Уточним позже</span></div><div class="summary-total"><span>Итого</span><strong>${money(cartTotal())}</strong></div>${button(`Перейти к оформлению ${icon('arrow',18)}`,'checkout','primary btn-wide btn-lg')}<small>Это демо. Реальные платежи не выполняются.</small></aside></div>`:empty('cart','Корзина пуста','Добавьте товар из каталога — и он появится здесь.','open-search','Перейти в каталог')}</div>`;
  const orderStatusClass = (st) => st==='Завершён'?'success':st==='Отменён'?'danger':st==='Новый'?'blue':'soft';
  const ordersList = (seller=false) => {const arr=seller?model.orders.filter(o=>o.seller==='archive'):model.orders;return arr.length?`<div class="orders-list">${arr.slice().reverse().map(o=>`<div class="order-card panel"><div class="order-info"><div><strong>Заказ № ${escapeHTML(o.id)}</strong><p>${dateLabel(o.createdAt,true)} · ${escapeHTML(community(o.seller).name)}</p></div>${badge(o.status,orderStatusClass(o.status))}</div><div class="order-products">${o.items.map(i=>{const p=product(i.id);return `<span>${escapeHTML(p?.title||i.id)} × ${i.qty}</span>`;}).join('')}</div><div class="order-bottom"><strong>${money(o.total)}</strong><span class="order-payment">${icon('info',15)} Оплата не подключена (демо)</span>${seller&&o.status!=='Завершён'&&o.status!=='Отменён'?`<div class="order-controls">${button('Следующий статус','next-order','outline',`data-id="${o.id}"`)}${button('Отменить','cancel-order','ghost',`data-id="${o.id}"`)}</div>`:''}</div></div>`).join('')}</div>`:empty('bag','Заказов пока нет',seller?'Как только покупатель оформит демозаказ, он появится здесь.':'Заказы появятся здесь после оформления первой покупки.',seller?'switch-buyer':'open-search',seller?'Открыть Маркет':'Найти товары');};
