  const dropsPage = (id) => {const d=drop(id);if(!d)return notFound();const s=community(d.seller);const live=d.status==='live';const finished=['soldout','ended'].includes(d.status);return `<div class="drop-page">${breadcrumb('market','К Маркету')}<div class="drop-head panel"><div class="drop-cover" style="--visual:#e5e2db">${illustration(product(d.itemIds[0])||model.products[0])}<img src="${escapeHTML(d.cover)}" alt="${escapeHTML(d.title)}" onerror="this.style.display='none'"/></div><div class="drop-info">${badge(dropLabel(d),live?'success':finished?'soft':'blue')}<p class="eyebrow">ЛИМИТИРОВАННАЯ КОЛЛЕКЦИЯ</p><h1>${escapeHTML(d.title)}</h1><p class="drop-subtitle">${escapeHTML(d.subtitle)}</p><div class="seller-mini">${sellerAvatar(s)} <strong>${escapeHTML(s.name)}</strong></div><p class="drop-description">${escapeHTML(d.description)}</p>${d.status==='announced'?`<div class="countdown-box"><span>До старта осталось</span><strong data-countdown="${d.id}">${countdown(d.startsAt)}</strong><small>Старт: ${dateLabel(d.startsAt,true)}</small></div>${button(`${icon('bell',18)} ${model.reminders.includes(d.id)?'Напоминание включено':'Напомнить о запуске'}`,'remind',model.reminders.includes(d.id)?'outline btn-lg':'primary btn-lg',`data-id="${d.id}"`)}`:live?`<div class="live-box">${icon('check',18)} Дроп открыт — товары доступны к покупке</div>`:`<div class="live-box muted">Коллекция завершена. Следите за следующими запусками.</div>`}<p class="demo-explain">Уведомления и запуск имитируются внутри браузера.</p></div></div><section class="block">${sectionHeader('В коллекции',`${d.itemIds.length} товара · ${live?'можно заказать':finished?'дроп завершён':'продажи ещё не начались'}`)}<div class="products-grid">${d.itemIds.map((id,i)=>{const p=product(id);if(!p)return '';return `<div class="drop-product-wrap">${productCard(p,i)}${!live?`<div class="drop-locked">${icon(finished?'check':'clock',17)} ${finished?'Дроп завершён':'Продажи с начала дропа'}</div>`:''}</div>`;}).join('')}</div></section></div>`;};
  const notFound = () => empty('search','Страница не найдена','Откройте Маркет, чтобы продолжить.','switch-buyer','Открыть Маркет');
