  const overview = () => {const active=model.orders.filter(o=>o.status!=='Отменён');const revenue=active.reduce((s,o)=>s+o.total,0);const low=model.products.filter(p=>p.seller==='archive'&&p.stock<=2);return `<div>${pageIntro('КАБИНЕТ ПРОДАВЦА','Обзор магазина',`Добро пожаловать обратно. Вот что происходит в «Архив 92».`,button(`${icon('plus',18)} Добавить товар`,'new-product','primary'))}${!model.connected?`<div class="notice">Сообщество не подключено. <button data-action="navigate" data-route="studio/settings">Настроить подключение</button></div>`:''}<div class="stats-grid">${statCard('Заказов',fmt.format(active.length),'+ новые заказы за время демо','bag')}${statCard('Сумма заказов',money(revenue),'Не является оплаченной выручкой','wallet')}${statCard('Товаров в каталоге',fmt.format(model.products.filter(p=>p.seller==='archive').length),'Опубликованные товары','box')}${statCard('Скоро дроп',fmt.format(model.drops.filter(d=>d.seller==='archive'&&d.status==='announced').length),'Запланированные коллекции','fire')}</div><div class="dashboard-grid"><section class="panel dashboard-section"><div class="section-header"><h2>Последние заказы</h2><button class="text-link" data-action="navigate" data-route="studio/orders">Все заказы ${icon('arrow',16)}</button></div>${active.length?`<div class="mini-orders">${active.slice(-3).reverse().map(o=>`<div><span>№ ${o.id}</span><strong>${money(o.total)}</strong>${badge(o.status,orderStatusClass(o.status))}</div>`).join('')}</div>`:empty('bag','Новых заказов нет','Оформите демозаказ в покупательской части.','switch-buyer','Перейти в Маркет')}</section><section class="panel dashboard-section"><div class="section-header"><h2>Ближайшие дропы</h2><button class="text-link" data-action="navigate" data-route="studio/drops">Управление ${icon('arrow',16)}</button></div>${model.drops.filter(d=>d.seller==='archive').slice(0,1).map(d=>`<div class="next-drop">${pImage(product(d.itemIds[0]))}<div><strong>${escapeHTML(d.title)}</strong><p>${dropLabel(d)}</p><small>${dateLabel(d.startsAt,true)}</small></div></div>`).join('')||'<p>Пока нет дропов.</p>'}</section></div><section class="block">${sectionHeader('Товары, требующие внимания','У этих позиций заканчивается остаток','В каталог','studio/products')}<div class="low-stock-grid">${low.map(p=>`<button class="low-stock" data-action="navigate" data-route="studio/products">${pImage(p)}<div><b>${escapeHTML(p.title)}</b><span>Осталось: ${p.stock} шт.</span></div>${icon('arrow',16)}</button>`).join('')||'<div class="panel muted pad">Все остатки в норме</div>'}</div></section></div>`;};
  const sellerProducts = () => {const list=model.products.filter(p=>p.seller==='archive');return `<div>${pageIntro('МАГАЗИН · АРХИВ 92','Товары',`Редактируйте каталог, цены и остатки.`,button(`${icon('plus',18)} Добавить товар`,'new-product','primary'))}<div class="panel table-panel"><div class="table-top"><strong>${list.length} товаров</strong><span>Данные сохранены в этом браузере</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Товар</th><th>Категория</th><th>Цена</th><th>Остаток</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="table-product">${pImage(p)}<span>${escapeHTML(p.title)}</span></div></td><td>${escapeHTML(p.category)}</td><td><strong>${money(p.price)}</strong></td><td><div class="stock-editor"><button data-action="stock-down" data-id="${p.id}" aria-label="Уменьшить остаток">${icon('minus',15)}</button><b>${p.stock}</b><button data-action="stock-up" data-id="${p.id}" aria-label="Увеличить остаток">${icon('plus',15)}</button></div></td><td><button class="icon-btn" title="Редактировать" data-action="edit-product" data-id="${p.id}">${icon('edit',18)}</button></td></tr>`).join('')}</tbody></table></div></div></div>`;};
  const sellerOrders = () => `<div>${pageIntro('МАГАЗИН · АРХИВ 92','Заказы','Меняйте статусы и отслеживайте выполнение демонстрационных заказов.')}${ordersList(true)}</div>`;
  const sellerDrops = () => `<div>${pageIntro('МАГАЗИН · АРХИВ 92','Дропы','Запускайте небольшие коллекции и собирайте интерес заранее.',button(`${icon('plus',18)} Создать дроп`,'new-drop','primary'))}<div class="seller-drop-list">${model.drops.filter(d=>d.seller==='archive').map(d=>`<div class="panel seller-drop-row"><div class="seller-drop-photo"><img src="${escapeHTML(d.cover)}" alt="" onerror="this.style.display='none'"/></div><div class="seller-drop-text">${badge(dropLabel(d),d.status==='live'?'success':'soft')}<h3>${escapeHTML(d.title)}</h3><p>${d.itemIds.length} товара · ${dateLabel(d.startsAt,true)}</p><small>${model.reminders.includes(d.id)?'Вы подписались на уведомление':'Напоминания доступны покупателям'}</small></div><div class="seller-drop-actions">${button('Посмотреть','view-drop','outline',`data-id="${d.id}"`)}${d.status==='announced'?button(`${icon('fire',16)} Запустить демо`,'launch-drop','primary',`data-id="${d.id}"`):d.status==='live'?button('Завершить дроп','end-drop','outline',`data-id="${d.id}"`):''}</div></div>`).join('')||empty('fire','Нет дропов','Создайте первую лимитированную коллекцию.','new-drop','Создать дроп')}</div><div class="notice">${icon('info',17)} В живой версии старт должен зависеть от времени, часового пояса и серверного остатка. Здесь запуск включается вручную для демонстрации.</div></div>`;
  const analyticsDataset = () => {let posts=demoPosts.filter(x=>ui.analyticsProduct==='all'||x.product===ui.analyticsProduct);const factor=ui.period===7?.29:ui.period===90?2.35:1;const sum=(field)=>Math.round(posts.reduce((s,p)=>s+p[field],0)*factor);return {posts,views:sum('views'),opens:sum('opens'),orders:sum('orders'),paid:sum('paid'),factor};};
  const areaChart = (period,metric) => {const count=period===7?7:period===90?14:12;const ys=Array.from({length:count},(_,i)=>[22,35,28,51,43,62,50,70,59,82,68,94,74,88][i]||60).map((n,i)=>Math.max(10,n+(metric==='orders'?-10:0)+(period===7?i*2:0)));const coords=ys.map((v,i)=>[32+i*644/(count-1),188-v*1.55]);const path=coords.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)} ${y.toFixed(1)}`).join(' ');return `<svg class="area-chart" viewBox="0 0 710 215" role="img" aria-label="Динамика ${metric==='orders'?'заказов':'открытий'} за ${period} дней"><defs><linearGradient id="areaFade" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#0077ff" stop-opacity=".22"/><stop offset="1" stop-color="#0077ff" stop-opacity="0"/></linearGradient></defs>${[42,89,136,183].map(y=>`<line x1="32" x2="678" y1="${y}" y2="${y}" stroke="currentColor" stroke-opacity=".1" stroke-dasharray="5 6"/>`).join('')}<path d="${path} L676 199 L32 199 Z" fill="url(#areaFade)"/><path d="${path}" fill="none" stroke="#0077ff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${coords.map(([x,y],i)=>i===coords.length-1?`<circle cx="${x}" cy="${y}" r="5" fill="#0077ff" stroke="white" stroke-width="3"/>`:'').join('')}</svg>`;};
  const demographic = () => {const age=[['<18',4,4],['18–24',28,21],['25–34',22,13],['35–44',6,5],['45–54',2,1],['55+',1,1]];return `<div class="demographic-bars">${age.map(([l,m,f])=>`<div class="age-column"><div class="age-bars"><span class="age-male" style="height:${m/28*100}%" title="Мужчины ${m}%"></span><span class="age-female" style="height:${f/28*100}%" title="Женщины ${f}%"></span></div><small>${l.replace('<','&lt;')}</small></div>`).join('')}</div><div class="chart-legend"><span><i class="dot blue"></i> Мужчины · 58%</span><span><i class="dot pink"></i> Женщины · 42%</span></div>`;};
